import { PipelineStage } from '../interfaces/pipeline-stage';
import { ObjectFactory } from '../models/common-types';
import { LogEvent } from '../models/log-event';

function deepClone<T>(obj: T): T {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }
  if (obj instanceof Date) {
    return new Date(obj.getTime()) as any;
  }
  if (obj instanceof Array) {
    return obj.map((item) => deepClone(item)) as any;
  }
  if (obj instanceof Object) {
    const clonedObj: any = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        clonedObj[key] = deepClone((obj as any)[key]);
      }
    }
    return clonedObj;
  }
  return obj;
}

export class EnrichStage implements PipelineStage {
  public constructor(private enricher: object | ObjectFactory) {}

  public process(events: LogEvent[]): LogEvent[] {
    return events.map((event) => {
      const enrichedProps =
        this.enricher instanceof Function
          ? this.enricher(deepClone(event.properties))
          : this.enricher;

      const mergedEnriched = { ...event.enrichedProperties, ...enrichedProps };

      return new LogEvent(
        event.timestamp,
        event.level,
        event.message,
        event.properties,
        event.unboundProperties,
        mergedEnriched,
        event.error
      );
    });
  }

  public async flush(): Promise<void> {
    return Promise.resolve();
  }
}

import { PipelineStage } from '../interfaces/pipeline-stage';
import { LogEvent } from '../models/log-event';

export class FilterStage implements PipelineStage {
  public constructor(private predicate: (event: LogEvent) => boolean) {}

  public process(events: LogEvent[]): LogEvent[] {
    return events.filter(this.predicate);
  }

  public async flush(): Promise<void> {
    return Promise.resolve();
  }
}

import { PipelineStage } from '../interfaces/pipeline-stage';
import { LoggerConfiguration } from '../logger-configuration';
import { LogEvent } from '../models/log-event';
import { Pipeline } from '../pipeline';

export class ForkStage implements PipelineStage {
  private pipeline: Pipeline;

  public constructor(configureFork: (forkConfig: LoggerConfiguration) => void) {
    const forkConfig = new LoggerConfiguration();
    configureFork(forkConfig);
    this.pipeline = forkConfig.createPipelineInstance();
  }

  public process(events: LogEvent[]): LogEvent[] {
    this.pipeline.emit(events);
    return events;
  }

  public flush(): Promise<void> {
    return this.pipeline.flush();
  }
}

import { LogEventLevel } from './log-event-level';
import { MessageParser } from './message-parser';

export class LogEvent {
  public constructor(
    public timestamp: string,
    public level: LogEventLevel,
    public message: MessageParser,
    public properties: Record<string, any>,
    public unboundProperties: Array<any>,
    public enrichedProperties: Record<string, any>,
    public error: Error | null = null
  ) {}
}

